def simple_calculator(num1, operator, num2):
    supported_operators = ['+', '-', '*', '/']
    if operator not in supported_operators:
        return f"Error: Invalid operator '{operator}'. Supported are {', '.join(supported_operators)}"

    if operator == '+':
        return num1 + num2
    elif operator == '-':
        return num1 - num2
    elif operator == '*':
        return num1 * num2
    elif operator == '/':
        if num2 == 0:
            return 'Error: Division by zero is not allowed.'
        return num1 / num2

# Test cases for various scenarios, including valid, invalid, and edge cases.
if __name__ == '__main__':
    results = []
    results.append(simple_calculator(10, '+', 5))
    results.append(simple_calculator(10, '-', 3))
    results.append(simple_calculator(7, '*', 8))
    results.append(simple_calculator(100, '/', 10))
    results.append(simple_calculator(15, '/', 0))
