import sys


def is_prime(n):
    """Return True if the positive integer n is a prime number."""
    if not isinstance(n, int):
        raise TypeError("n must be an integer: {!r}".format(n))
    if n < 1:
        raise ValueError("n must be positive: {}".format(n))
    if n < 4:
        return n in (2, 3)
    if n % 2 == 0:
        return False
    divisor = 3
    while divisor * divisor <= n:
        if n % divisor == 0:
            return False
        divisor += 2
    return True


def primes_up_to(limit):
    """Return the list of primes not exceeding limit, using a sieve."""
    if limit < 2:
        return []
    sieve = bytearray([1]) * (limit + 1)
    sieve[0:2] = bytes([0, 0])
    for candidate in range(2, int(limit ** 0.5) + 1):
        if sieve[candidate]:
            start = candidate * candidate
            sieve[start::candidate] = bytes(len(sieve[start::candidate]))
    return [number for number, flag in enumerate(sieve) if flag]


def prime_factors(n):
    """Return the prime factors of n in ascending order, with multiplicity."""
    if n < 1:
        raise ValueError("cannot factor {}".format(n))
    factors = []
    remainder = n
    while remainder % 2 == 0:
        factors.append(2)
        remainder //= 2
    divisor = 3
    while divisor * divisor <= remainder:
        while remainder % divisor == 0:
            factors.append(divisor)
            remainder //= divisor
        divisor += 2
    if remainder > 1:
        factors.append(remainder)
    return factors


def describe(n):
    """Build a one-line human-readable classification of n."""
    if n == 1:
        return "{:>8} is neither prime nor composite".format(n)
    if is_prime(n):
        return "{:>8} is prime".format(n)
    pieces = [str(factor) for factor in prime_factors(n)]
    return "{:>8} = {}".format(n, " * ".join(pieces))


def main(argv):
    """Classify every number given on the command line."""
    samples = [int(arg) for arg in argv[1:]]
    if not samples:
        samples = [1, 10] + primes_up_to(12)
        samples.append(1000003)
    for sample in samples:
        print(describe(sample))
    small = primes_up_to(50)
    print("primes up to 50: " + ", ".join(str(prime) for prime in small))
    print("count {} largest {}".format(len(small), small[-1]))


if __name__ == "__main__":
    main(sys.argv)

