def merge_dictionaries(dict1,dict2):
    """Return a new dict holding every pair from both; dict2 wins on conflicts."""
    if not isinstance(dict1,dict):
        raise TypeError("dict1 must be a dictionary: %s" % type(dict1).__name__)
    if not isinstance(dict2,dict):
        raise TypeError("dict2 must be a dictionary: %s" % type(dict2).__name__)
    merged = dict(dict1)
    merged.update(dict2)
    return merged


def merge_all(dictionaries):
    """Merge a sequence of dictionaries left to right so later ones win."""
    result = {}
    for current in dictionaries:
        result = merge_dictionaries(result,current)
    return result


def conflicting_keys(dict1,dict2):
    """Keys present in both dictionaries whose values actually differ."""
    shared = set(dict1) & set(dict2)
    return sorted(key for key in shared if dict1[key] != dict2[key])


def format_pair(key,value):
    """Render a single key/value pair for display."""
    return "%s=%r" % (key,value)


def format_dictionary(mapping):
    """Render a dictionary as a stable readable one-liner."""
    if not mapping:
        return "{}"
    parts = [format_pair(key,mapping[key]) for key in sorted(mapping)]
    return "{%s}" % ", ".join(parts)


def merge_report(dict1,dict2):
    """Merge two dictionaries and describe the result as report lines."""
    merged = merge_dictionaries(dict1,dict2)
    lines = [
        "left  " + format_dictionary(dict1),
        "right " + format_dictionary(dict2),
    ]
    for key in conflicting_keys(dict1,dict2):
        change = "%r -> %r" % (dict1[key],dict2[key])
        lines.append("  override %s: %s" % (key,change))
    added = sorted(set(dict2) - set(dict1))
    if added:
        lines.append("  added " + ", ".join(added))
    lines.append("merged " + format_dictionary(merged))
    lines.append("keys   " + (", ".join(sorted(merged)) or "(none)"))
    return lines


def main():
    basic_left = {"a": 1,"b": 2}
    basic_right = {"b": 3,"c": 4}
    server = {"host": "localhost","port": 80}
    patch = {"port": 8080,"debug": True}
    pairs = [
        (basic_left,basic_right),
        (server,patch),
        ({},{"only": "right"}),
        ({"x": None},{}),
    ]
    for left,right in pairs:
        print("\n".join(merge_report(left,right)))
        print()

    defaults = {"retries": 3,"timeout": 30}
    profile = {"timeout": 5,"verbose": True}
    overrides = {"retries": 1,"region": "eu-west"}
    layers = [
        defaults,
        profile,
        overrides,
    ]
    settings = merge_all(layers)
    print("layered configuration: " + format_dictionary(settings))
    changed = conflicting_keys(defaults,settings)
    print("changed from defaults: " + ", ".join(changed))


if __name__ == "__main__":
    main()

