import math

def geometric_mean(numbers):
    if not numbers:
        raise ValueError(
            "Input list cannot be empty",
            "for geometric mean calculation"
        )
    for num in numbers:
        if not isinstance(num, (int, float)):
            raise TypeError(
                "All elements must be numbers",
                "integers or floats"
            )
        if num <= 0:
            raise ValueError(
                "All numbers must be positive",
                "for geometric mean"
            )

    product = 1.0
    for num in numbers:
        product *= num

    n = len(numbers)
    return math.pow(
        product,
        1/n
    )

if __name__ == '__main__':
    # Test cases
    print(
        geometric_mean([2, 8]),
        "Expected: 4.0"
    )
    print(
        geometric_mean([1, 1, 1]),
        "Expected: 1.0"
    )
    print(
        geometric_mean([3, 4, 5]),
        "Expected: 3.9148676415951756"
    )
    print(
        geometric_mean([0.5, 2, 4.5, 8]),
        "Expected: 2.5190967389816285"
    )

    try:
        geometric_mean([])
    except ValueError as e:
        print(
            "Caught expected error:",
            e
        )

    try:
        geometric_mean([1, -2, 3])
    except ValueError as e:
        print(
            "Caught expected error:",
            e
        )

    try:
        geometric_mean([1, "a", 3])
    except TypeError as e:
        print(
            "Caught expected error:",
            e
        )

