import calendar


def days_in_month(year, month):
    return calendar.monthrange(year, month)[1]


def validate_date(year, month, day):
    fields = (
        ('year', year),
        ('month', month),
        ('day', day),
    )
    for name, value in fields:
        if not isinstance(value, int):
            raise TypeError(f"{name} must be an integer, got {type(value).__name__}")
    if not 1 <= month <= 12:
        raise ValueError(f"month out of range: {month}")
    limit = days_in_month(year, month)
    if not 1 <= day <= limit:
        raise ValueError(f"day out of range for month {month}: {day}")


def format_date(year, month, day):
    validate_date(year, month, day)
    return f"{year:04d}-{month:02d}-{day:02d}"


def format_long_date(year, month, day):
    validate_date(year, month, day)
    return f"{calendar.month_name[month]} {day}, {year}"


def day_of_year(year, month, day):
    validate_date(year, month, day)
    total = day
    for earlier in range(1, month):
        total += days_in_month(year, earlier)
    return total


def parse_parts(text):
    parts = text.split('-')
    if len(parts) != 3:
        raise ValueError(f"expected three '-' separated fields in {text!r}")
    return tuple(int(part) for part in parts)


def describe(text):
    year, month, day = parse_parts(text)
    iso = format_date(year, month, day)
    long_form = format_long_date(year, month, day)
    ordinal = day_of_year(year, month, day)
    return f"{iso} | {long_form} | day {ordinal} of the year"


def main():
    samples = [
        '2023-7-15',
        '2020-1-1',
        '2024-2-29',
        '1999-12-31',
    ]
    for text in samples:
        print(describe(text))
    for text in ('2023-13-1', '2023-2-30'):
        try:
            print(describe(text))
        except ValueError as exc:
            print(f"rejected {text}: {exc}")


if __name__ == '__main__':
    main()

