TOO_HIGH = 'Too high'
TOO_LOW = 'Too low'
CORRECT = 'Correct!'
NUMERIC_TYPES = (int, float)


def _as_int(label, value):
    """Return ``value`` as an int, rejecting anything that is not a whole number."""
    if isinstance(value, bool):
        raise TypeError('{} must not be a boolean'.format(label))
    if not isinstance(value, NUMERIC_TYPES):
        raise TypeError('{} must be a number: {!r}'.format(label, value))
    if isinstance(value, float) and not value.is_integer():
        raise ValueError('{} must be a whole number: {!r}'.format(label, value))
    return int(value)


def guess_number(secret_number, guess):
    """Compare a guess against the secret number and describe the result."""
    secret = _as_int('secret_number', secret_number)
    attempt = _as_int('guess', guess)
    if attempt > secret:
        return TOO_HIGH
    if attempt < secret:
        return TOO_LOW
    return CORRECT


def solve(secret_number, low=1, high=100):
    """Binary-search the secret within the inclusive range and list every guess."""
    bottom = _as_int('low', low)
    top = _as_int('high', high)
    if bottom > top:
        raise ValueError('empty range: {} > {}'.format(bottom, top))
    secret = _as_int('secret_number', secret_number)
    if not bottom <= secret <= top:
        raise ValueError('{} lies outside the range'.format(secret))
    guesses = []
    while bottom <= top:
        middle = (bottom + top) // 2
        guesses.append(middle)
        verdict = guess_number(secret, middle)
        if verdict == CORRECT:
            break
        if verdict == TOO_HIGH:
            top = middle - 1
        else:
            bottom = middle + 1
    return guesses


def format_round(secret_number, guesses):
    """Render one solved round as a single table row."""
    trail = ', '.join(str(step) for step in guesses)
    return '{:>7} | {:>7} | {}'.format(secret_number, len(guesses), trail)


def report(secrets, low=1, high=100):
    """Solve every secret and build a printable report of the results."""
    header = '{:>7} | {:>7} | {}'.format('secret', 'tries', 'guesses')
    lines = [header, '-' * len(header)]
    for secret in secrets:
        guesses = solve(secret, low, high)
        lines.append(format_round(secret, guesses))
    return '\n'.join(lines)


def main():
    print(guess_number(10, 12))
    print(guess_number(10, 8))
    print(guess_number(10, 10))
    standard = [1, 7, 42, 63, 100]
    print(report(standard))
    wide = [250, 500, 999]
    print(report(wide, 200, 1000))


if __name__ == '__main__':
    main()

