import random
import string
from collections import Counter

CATEGORIES = (
    ("lower", string.ascii_lowercase),
    ("upper", string.ascii_uppercase),
    ("digit", string.digits),
)

LEVELS = (
    "weak",
    "medium",
    "strong",
)

DEMO_LENGTHS = (8, 16)


def alphabet():
    return "".join(pair[1] for pair in CATEGORIES)


def category_names():
    return [pair[0] for pair in CATEGORIES]


def generate_password(length):
    if not isinstance(length, int):
        raise TypeError("length must be an integer")
    if length < 1:
        raise ValueError("length must be at least 1")
    pool = alphabet()
    return "".join(random.choice(pool) for _ in range(length))


def classify(password):
    counts = dict.fromkeys(category_names(), 0)
    for char in password:
        for name, chars in CATEGORIES:
            if char in chars:
                counts[name] += 1
    return counts


def strength(password):
    counts = classify(password)
    families = sum(1 for count in counts.values() if count > 0)
    if len(password) >= 12 and families == len(CATEGORIES):
        return "strong"
    if len(password) >= 8 and families >= 2:
        return "medium"
    return "weak"


def format_row(password):
    counts = classify(password)
    cells = [password.ljust(16), str(len(password)).rjust(3)]
    for name in category_names():
        cells.append(str(counts[name]).rjust(3))
    cells.append(strength(password).rjust(7))
    return " | ".join(cells)


def header():
    titles = ["password".ljust(16), "len"]
    titles.extend(name[:3] for name in category_names())
    titles.append("score".rjust(7))
    line = " | ".join(titles)
    return "\n".join([line, "-" * len(line)])


def batch(lengths):
    return [generate_password(length) for length in lengths]


