def sum_digits(n):
    """
    Calculates the sum of the digits of a given non-negative integer n.

    Args:
        n: The non-negative integer,
           whose digits are to be summed.

    Returns:
        The sum of the digits of n.
    """
    if not isinstance(n, int):
        raise TypeError(
            "Input must be an integer",
            f"Received type: {type(n)}"
        )
    if n < 0:
        raise ValueError(
            "Input must be non-negative",
            f"Received value: {n}"
        )

    digit_sum = 0
    s_n = str(n)
    for digit_char in s_n:
        digit_sum += int(
            digit_char,
            10
        )
    return digit_sum

if __name__ == '__main__':
    test_cases = [
        (123, 6),
        (9, 9),
        (0, 0),
        (10, 1),
        (98765, 35),
        (11111, 5)
    ]

    for number, expected_sum in test_cases:
        actual_sum = sum_digits(
            number
        )
        print(
            f"Sum of digits for {number}: {actual_sum}",
            f"(Expected: {expected_sum})"
        )
        assert actual_sum == expected_sum, \
            f"Test failed for {number}: Expected {expected_sum}, got {actual_sum}"

    try:
        sum_digits(
            -5
        )
    except ValueError as e:
        print(
            f"Caught expected error for negative input: {e}",
            "This is good."
        )

    try:
        sum_digits(
            3.14
        )
    except TypeError as e:
        print(
            f"Caught expected error for non-integer input: {e}",
            "This is also good."
        )

