def is_anagram(s1, s2):
    def clean_string(text_input):
        return ''.join(
            char.lower() for char in text_input
            if char.isalnum()
        )

    cleaned_s1, cleaned_s2 = clean_string(s1), clean_string(s2)

    if len(cleaned_s1) != len(cleaned_s2):
