def is_valid_url(url):
    schemes = ['http://', 'https://', 'ftp://', 'sftp://', 'ftps://']
    valid_schemes = ['http://', 'https://']

    if not isinstance(url, str):
        return False

    scheme_found = False
    for scheme in valid_schemes:
        if url.startswith(scheme):
            scheme_found = True
            break

    if not scheme_found:
        return False

    parts = url.split('://', 1)
    if len(parts) < 2:
        return False

    domain_path = parts[1]

    if '.' not in domain_path:
        return False

    uncommon_chars = [' ', '\t', '\n', '\r', '\f', '\v']
    if any(char in domain_path for char in uncommon_chars):
        return False

    disallowed_starts = ['/', '?', '#', ':', '@']
    if domain_path.startswith(tuple(disallowed_starts)):
        return False

    common_tlds = ['com', 'org', 'net', 'edu', 'gov', 'io', 'co', 'info', 'biz', 'tech']
    if not any(f".{tld}" in domain_path for tld in common_tlds):
        if '.' not in domain_path[domain_path.rfind('/')+1:]: # Check for dot in last segment
            return False

    return True

