"""Harmonic mean utilities with validation, parsing and a small report driver."""

from math import fsum, prod

SEQUENCE_TYPES = (list, tuple)
NUMBER_TYPES = (int, float)


def validate(numbers):
    """Return the input as a list of positive floats."""
    if not isinstance(numbers, SEQUENCE_TYPES):
        raise TypeError("numbers must be a list or tuple of positive numbers")
    values = []
    for index, item in enumerate(numbers):
        if not isinstance(item, NUMBER_TYPES):
            raise TypeError("element %d is not a number: %r" % (index, item))
        value = float(item)
        if value <= 0.0:
            raise ValueError("element %d is not positive: %r" % (index, value))
        values.append(value)
    if not values:
        raise ValueError("numbers must contain at least one value")
    return values


def harmonic_mean(numbers):
    """Reciprocal of the arithmetic mean of the reciprocals."""
    values = validate(numbers)
    reciprocals = [1.0 / value for value in values]
    return len(values) / fsum(reciprocals)


def arithmetic_mean(numbers):
    values = validate(numbers)
    return fsum(values) / len(values)


def geometric_mean(numbers):
    values = validate(numbers)
    return prod(values) ** (1.0 / len(values))


def means(numbers):
    """Map mean names to their values for a single data set."""
    return {
        "harmonic": harmonic_mean(numbers),
        "geometric": geometric_mean(numbers),
        "arithmetic": arithmetic_mean(numbers),
    }


def parse_numbers(text):
    """Read a comma separated data set into a list of floats."""
    return [float(part) for part in text.split(",")]


def format_row(numbers):
    table = means(numbers)
    data = ", ".join("%g" % value for value in numbers)
    return "[{}] -> H={harmonic:.6f} G={geometric:.6f} A={arithmetic:.6f}".format(
        data, **table
    )


def report(rows):
    lines = []
    for text in rows:
        lines.append(format_row(parse_numbers(text)))
    return "\n".join(lines)


def main():
    rows = [
        "1,2,4",
        "10,10,10",
        "2.5,3.5,7,12",
        "40,60",
    ]
    print(report(rows))
    for text in ("1,0,3", "1,-2"):
        try:
            harmonic_mean(parse_numbers(text))
        except ValueError as error:
            print("rejected %s: %s" % (text, error))


if __name__ == "__main__":
    main()

