FEEDBACK_HIGH = 'Too high'
FEEDBACK_LOW = 'Too low'
FEEDBACK_EXACT = 'Correct!'


def is_plain_int(value):
    """True for real integers, excluding the bool subclass."""
    if isinstance(value, bool):
        return False
    return isinstance(value, int)


def check_int(name, value):
    """Raise TypeError unless value is a plain (non-boolean) integer."""
    if not is_plain_int(value):
        raise TypeError('{} must be an int but was {!r}'.format(name, value))


def simulate_guess(target, guess):
    """Return the feedback string for a single guess against target."""
    check_int('target', target)
    check_int('guess', guess)
    if guess > target:
        return FEEDBACK_HIGH
    if guess < target:
        return FEEDBACK_LOW
    return FEEDBACK_EXACT


def play_round(target, guesses):
    """Feed a sequence of guesses to the game, stopping once it is solved."""
    transcript = []
    attempt = 0
    for guess in guesses:
        attempt += 1
        feedback = simulate_guess(target, guess)
        transcript.append({
            'attempt': attempt,
            'guess': guess,
            'feedback': feedback,
        })
        if feedback == FEEDBACK_EXACT:
            break
    return transcript


def summarize(target, transcript):
    """Collapse a transcript into a small dictionary of statistics."""
    highs = 0
    lows = 0
    for entry in transcript:
        if entry['feedback'] == FEEDBACK_HIGH:
            highs += 1
        elif entry['feedback'] == FEEDBACK_LOW:
            lows += 1
    return {
        'target': target,
        'attempts': len(transcript),
        'too_high': highs,
        'too_low': lows,
        'solved': bool(transcript) and transcript[-1]['feedback'] == FEEDBACK_EXACT,
    }


def format_transcript(transcript):
    lines = []
    for entry in transcript:
        label = '  #{} guessed {:>4}'.format(entry['attempt'], entry['guess'])
        lines.append(label + ' -> ' + entry['feedback'])
    return '\n'.join(lines)


def format_summary(stats):
    outcome = 'solved' if stats['solved'] else 'gave up'
    template = '  target {target}: {outcome} in {attempts} guess(es)'
    template += ' [high={too_high} low={too_low}]'
    return template.format(outcome=outcome, **stats)


def main():
    warm_up = [5, 7]
    over_shoot = [9, 7]
    hopeless = [1, 2]
    scenarios = [
        (7, warm_up),
        (7, over_shoot),
        (100, hopeless),
    ]
    for target, guesses in scenarios:
        transcript = play_round(target, guesses)
        print(format_transcript(transcript))
        print(format_summary(summarize(target, transcript)))
        print()


if __name__ == '__main__':
    main()

