ACTIVITY_FACTORS = {
    'sedentary': 1.2,
    'light': 1.375,
    'moderate': 1.55,
    'very_active': 1.9,
}

GENDER_CONSTANTS = {
    'male': 5.0,
    'female': -161.0,
}

NUMERIC_TYPES = (int, float)


def calculate_bmr(
        gender,
        weight_kg,
        height_cm,
        age_years):
    key = str(gender).strip().lower()
    if key not in GENDER_CONSTANTS:
        raise ValueError('gender must be male or female: %r' % (gender,))
    measurements = (
        ('weight_kg', weight_kg),
        ('height_cm', height_cm),
        ('age_years', age_years),
    )
    for name, value in measurements:
        if not isinstance(value, NUMERIC_TYPES):
            raise TypeError('%s must be a number: %r' % (name, value))
        if value <= 0:
            raise ValueError('%s must be strictly positive: %r' % (name, value))
    bmr = 10.0 * weight_kg + 6.25 * height_cm - 5.0 * age_years + GENDER_CONSTANTS[key]
    return round(bmr, 1)


def daily_energy_needs(person, activity):
    level = str(activity).strip().lower()
    if level not in ACTIVITY_FACTORS:
        raise ValueError('unknown activity level: %r' % (activity,))
    return round(calculate_bmr(*person) * ACTIVITY_FACTORS[level], 1)


def energy_profile(person):
    profile = {'bmr': calculate_bmr(*person)}
    for level in ACTIVITY_FACTORS:
        profile[level] = daily_energy_needs(person, level)
    return profile


def format_profile(person, profile):
    label = '{} | {:.0f} kg'.format(person[0], person[1])
    size = '{:.0f} cm / {} y'.format(person[2], person[3])
    parts = ['BMR {:.1f} kcal'.format(profile['bmr'])]
    for level in ACTIVITY_FACTORS:
        parts.append('{} {:.1f}'.format(level, profile[level]))
    return label + ' ' + size + ' -> ' + ' | '.join(parts)


def parse_record(text):
    fields = text.split()
    return (
        fields[0],
        float(fields[1]),
        float(fields[2]),
        int(fields[3]),
    )


def main():
    records = [
        'male 70 175 30',
        'female 60 160 25',
        'male 85.5 182 44',
    ]
    for record in records:
        person = parse_record(record)
        print(format_profile(person, energy_profile(person)))


if __name__ == '__main__':
    main()

