import random
from collections import Counter

FACES = ('Heads', 'Tails')


def simulate_coin_flip():
    """Flip a fair coin once and return either 'Heads' or 'Tails'."""
    result = random.choice(FACES)
    return result


def flip_many(count):
    """Flip the coin `count` times and return the list of outcomes."""
    if not isinstance(count, int):
        raise TypeError('count must be an integer, got %r' % (count,))
    if count < 1:
        raise ValueError('count must be at least 1, got %d' % count)
    return [simulate_coin_flip() for _ in range(count)]


def tally(outcomes):
    """Count how often each face appeared, always reporting both faces."""
    counts = Counter(outcomes)
    return {face: counts.get(face, 0) for face in FACES}


def longest_streak(outcomes):
    """Return (face, length) for the longest run of identical outcomes."""
    best_face = outcomes[0]
    best_length = 1
    current_length = 1
    for index in range(1, len(outcomes)):
        if outcomes[index] == outcomes[index - 1]:
            current_length += 1
        else:
            current_length = 1
        if current_length > best_length:
            best_length = current_length
            best_face = outcomes[index]
    return best_face, best_length


def format_report(outcomes):
    """Build a human readable summary of a sequence of flips."""
    counts = tally(outcomes)
    total = len(outcomes)
    lines = ['Flips: %d' % total]
    lines.append('Sequence: %s' % ', '.join(outcomes))
    for face in FACES:
        share = 100.0 * counts[face] / total
        detail = '%4d (%5.1f%%)' % (counts[face], share)
        lines.append('%-6s %s' % (face, detail))
    face, length = longest_streak(outcomes)
    lines.append('Longest streak: %d x %s' % (length, face))
    return '\n'.join(lines)


def main():
    random.seed(20260918)
    print('Single flip:', simulate_coin_flip())
    for size in (1, 20):
        print()
        print(format_report(flip_many(size)))
    for bad in (0, 2.5):
        try:
            flip_many(bad)
        except (TypeError, ValueError) as exc:
            print('Rejected %r: %s' % (bad, exc))


if __name__ == '__main__':
    main()

