def minutes_to_hh_mm(total_minutes):
    if not isinstance(total_minutes, int):
        raise TypeError("total_minutes must be an int")
    if total_minutes < 0:
        raise ValueError("total_minutes must not be negative")
    hours = total_minutes // 60
    minutes = total_minutes % 60
    return "{:02d}:{:02d}".format(hours, minutes)


def hh_mm_to_minutes(formatted_time):
    parts = formatted_time.split(":")
    if len(parts) != 2:
        raise ValueError("expected a 'HH:MM' string, got %r" % (formatted_time,))
    minutes = int(parts[1])
    if minutes > 59:
        raise ValueError("minute field out of range in %r" % (formatted_time,))
    return int(parts[0]) * 60 + minutes


UNIT_SIZES = (
    ("day", 24 * 60),
    ("hour", 60),
    ("minute", 1),
)


def describe(total_minutes):
    remainder = total_minutes
    chunks = []
    for unit, size in UNIT_SIZES:
        amount = remainder // size
        remainder %= size
        if amount:
            suffix = "" if amount == 1 else "s"
            chunks.append("%d %s" % (amount, unit + suffix))
    if not chunks:
        return "0 minutes"
    return ", ".join(chunks)


def average_duration(durations):
    if not durations:
        raise ValueError("cannot average an empty list of durations")
    total = sum(hh_mm_to_minutes(item) for item in durations)
    return minutes_to_hh_mm(total // len(durations))


def report_line(entry, width):
    label = entry[0]
    value = entry[1]
    head = "%s  %s" % (label.ljust(width), minutes_to_hh_mm(value))
    return "%s  (%s)" % (head, describe(value))


def build_report(entries):
    width = max(len(entry[0]) for entry in entries)
    lines = [report_line(entry, width) for entry in entries]
    total = sum(entry[1] for entry in entries)
    total_entry = ("TOTAL", total)
    lines.append(report_line(total_entry, width))
    return "\n".join(lines)


def main():
    entries = [
        ("commute", 70),
        ("coding", 1440),
        ("standup", 15),
    ]
    print(build_report(entries))
    logged = [minutes_to_hh_mm(entry[1]) for entry in entries]
    print("average:", average_duration(logged))


if __name__ == "__main__":
    main()

