def reverse_each_word(sentence):
    words = sentence.split(
        ' '
    )
    reversed_words = []
    for word in words:
        reversed_word = word[
            ::-1
        ]
        reversed_words.append(
            reversed_word
        )
    return ' '.join(
        reversed_words
    )

