TEXT_TYPES = (str, bytes)
NUMBER_TYPES = (int, float)


def calculate_range(numbers):
    """Return the difference between the largest and smallest value."""
    values = validate_numbers(numbers)
    return max(values) - min(values)


def validate_numbers(numbers):
    """Coerce the input into a list of numbers, rejecting bad data."""
    if isinstance(numbers, TEXT_TYPES):
        raise TypeError("numbers must be a sequence of int/float values")
    values = list(numbers)
    if not values:
        raise ValueError("numbers must contain at least one value")
    for index, value in enumerate(values):
        is_number = isinstance(value, NUMBER_TYPES)
        if isinstance(value, bool) or not is_number:
            raise TypeError("bad value at position {0}: {1!r}".format(index, value))
    return values


def parse_numbers(text):
    """Read the numbers appearing in a line of text."""
    values = []
    for token in text.split():
        try:
            values.append(int(token))
        except ValueError:
            values.append(float(token))
    return validate_numbers(values)


def describe(numbers):
    """Build the ordered summary fields of a list of numbers."""
    values = validate_numbers(numbers)
    return [
        ("count", len(values)),
        ("minimum", min(values)),
        ("maximum", max(values)),
        ("mean", sum(values) / len(values)),
        ("range", calculate_range(values)),
    ]


def format_summary(numbers):
    """Produce a one-line readable report for a data set."""
    parts = []
    for name, value in describe(numbers):
        parts.append("{0}={1:g}".format(name, value))
    return " | ".join(parts)


def main():
    samples = [
        ("mixed", "1 5 2 8"),
        ("single", "10"),
        ("negatives", "-4 -12 -7 -1"),
        ("floats", "2.5 3.75 1.25 9.0"),
    ]
    spreads = []
    for label, text in samples:
        values = parse_numbers(text)
        spreads.append((label, calculate_range(values)))
        print("{0:>10}: {1}".format(label, format_summary(values)))
    widest = max(spreads, key=lambda pair: pair[1])
    print("widest spread: {0} ({1:g})".format(*widest))


if __name__ == "__main__":
    main()

