import random
from collections import Counter

SIDES = 6


def validate_count(num_dice):
    """Reject anything that is not a non-negative whole number of dice."""
    if not isinstance(num_dice, int):
        raise TypeError("num_dice must be an integer")
    if isinstance(num_dice, bool):
        raise TypeError("num_dice must be an integer, not a boolean")
    if num_dice < 0:
        raise ValueError("num_dice must be non-negative")


def roll_faces(num_dice):
    """Return the individual faces shown by num_dice dice."""
    validate_count(num_dice)
    return [random.randint(1, SIDES) for _ in range(num_dice)]


def simulate_dice_sum(num_dice):
    """Roll num_dice standard six-sided dice and return the sum of the faces."""
    return sum(roll_faces(num_dice))


def sum_bounds(num_dice):
    """Return the smallest and largest sums attainable with num_dice dice."""
    validate_count(num_dice)
    return num_dice, SIDES * num_dice


def simulate_many(num_dice, trials):
    """Run trials independent rolls and return the list of sums."""
    if trials < 1:
        raise ValueError("trials must be at least 1")
    return [simulate_dice_sum(num_dice) for _ in range(trials)]


def summarize(sums):
    """Describe a list of sums with its count, extremes and mean."""
    return {
        "trials": len(sums),
        "lowest": min(sums),
        "highest": max(sums),
        "mean": sum(sums) / len(sums),
    }


def histogram(sums, width=40):
    """Build text rows showing how often each sum occurred."""
    counts = Counter(sums)
    busiest = max(counts.values())
    rows = []
    for value in sorted(counts):
        bar = "#" * max(1, counts[value] * width // busiest)
        rows.append("{:>3} | {:<{}} {}".format(
            value,
            bar,
            width,
            counts[value],
        ))
    return rows


def report(num_dice, trials):
    """Print a sample roll and the statistics of many rolls."""
    faces = roll_faces(num_dice)
    low, high = sum_bounds(num_dice)
    print("Sample roll of {} dice: {} -> {}".format(
        num_dice,
        faces,
        sum(faces),
    ))
    print("Possible sums range from {} to {}".format(low, high))
    stats = summarize(simulate_many(num_dice, trials))
    print("Trials {trials} | lowest {lowest} | highest {highest} | mean {mean:.2f}".format(**stats))
    for line in histogram(simulate_many(num_dice, trials)):
        print(line)


def main():
    random.seed(20260918)
    plans = [
        (1, 600),
        (2, 1200),
        (5, 3000),
    ]
    for dice, trials in plans:
        report(dice, trials)
        print("-" * 52)


if __name__ == "__main__":
    main()

