MONTHS = [
    ("January", 31),
    ("February", 28),
    ("March", 31),
    ("April", 30),
    ("May", 31),
    ("June", 30),
    ("July", 31),
    ("August", 31),
    ("September", 30),
    ("October", 31),
    ("November", 30),
    ("December", 31),
]


def is_leap_year(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def days_in_month(year, month):
    if month == 2 and is_leap_year(year):
        return 29
    return MONTHS[month - 1][1]


def month_name(month):
    return MONTHS[month - 1][0]


def parse_date(date_str):
    parts = date_str.split('-')
    if len(parts) != 3 or not all(part.isdigit() for part in parts):
        raise ValueError("expected 'YYYY-MM-DD', got {!r}".format(date_str))
    if len(parts[0]) != 4:
        raise ValueError("year must have four digits in {!r}".format(date_str))
    numbers = [int(part) for part in parts]
    if not 1 <= numbers[1] <= 12:
        raise ValueError("month {} is out of range in {!r}".format(numbers[1], date_str))
    if not 1 <= numbers[2] <= days_in_month(numbers[0], numbers[1]):
        raise ValueError("day {} is out of range in {!r}".format(numbers[2], date_str))
    return tuple(numbers)


def to_ordinal(date):
    year = date[0]
    prior = year - 1
    total = prior * 365 + prior // 4 - prior // 100 + prior // 400
    for earlier_month in range(1, date[1]):
        total += days_in_month(year, earlier_month)
    return total + date[2]


def days_between_dates(start_date_str, end_date_str):
    start = parse_date(start_date_str)
    end = parse_date(end_date_str)
    return to_ordinal(end) - to_ordinal(start)


def format_date_long(date_str):
    date = parse_date(date_str)
    day_part = "{} {}".format(month_name(date[1]), date[2])
    return "{}, {}".format(day_part, date[0])


def describe_span(start_date_str, end_date_str):
    delta = days_between_dates(start_date_str, end_date_str)
    direction = "forward" if delta >= 0 else "backward"
    span = "{} -> {}".format(format_date_long(start_date_str), format_date_long(end_date_str))
    amount = "{} day(s) {}".format(abs(delta), direction)
    return "{}: {}".format(span, amount)


def main():
    pairs = [
        ('2023-01-01', '2023-01-05'),
        ('2023-01-01', '2022-12-25'),
        ('2020-02-28', '2020-03-01'),
        ('1999-12-31', '2000-01-01'),
        ('2021-06-15', '2021-06-15'),
    ]
    for start_date_str, end_date_str in pairs:
        print(describe_span(start_date_str, end_date_str))


if __name__ == '__main__':
    main()

