import random

def roll_die(num_sides):
    """
    Simulates a single roll of an N-sided die.

    Args:
        num_sides (int): The number of sides on the die,
                         must be greater than or equal to 1.

    Returns:
        int: A random integer between 1 and num_sides (inclusive).
    """
    if not isinstance(num_sides, int):
        raise TypeError(
            "num_sides must be an integer",
            "received type:", type(num_sides),
            "expected type:", int
        )
    if num_sides < 1:
        raise ValueError(
            "num_sides must be at least 1",
            "received:", num_sides,
            "minimum allowed:", 1
        )

    return random.randint(
        1,
        num_sides
    )

if __name__ == "__main__":


    print("Rolling a 6-sided die:", roll_die(6))


    print("Rolling a 20-sided die:", roll_die(20))


    print("Rolling a 4-sided die:", roll_die(4))


    print("Rolling a 100-sided die:", roll_die(100))


    print("Rolling a 2-sided die:", roll_die(2))


    results = [roll_die(6) for _ in range(5)]


    print("Five rolls of a 6-sided die:", results)





    try:
        roll_die(
            0
        )
