    validate_interval(first,"task 1")
    validate_interval(second,"task 2")
    return task1_start < task2_end and task2_start < task1_end


def overlap_window(first,second):
    if not has_overlap(*first,*second):
        return None
    start = max(first[0],second[0])
    end = min(first[1],second[1])
    return start,end


def format_hour(hour):
    suffix = "AM" if hour % 24 < 12 else "PM"
    display = hour % 12 or 12
    return f"{display}:00 {suffix}"


def format_interval(bounds):
    start,end = bounds
    return f"{format_hour(start)} - {format_hour(end)}"


def describe_pair(first,second):
    name1,interval1 = first
    name2,interval2 = second
    window = overlap_window(interval1,interval2)
    left = f"{name1} ({format_interval(interval1)})"
    right = f"{name2} ({format_interval(interval2)})"
    if window is None:
        return f"{left} and {right} do not overlap"
    hours = window[1] - window[0]
    return f"{left} and {right} overlap for {hours}h at {format_interval(window)}"


def find_conflicts(schedule):
    conflicts = []
    names = sorted(schedule)
    for index,name1 in enumerate(names):
        for name2 in names[index + 1:]:
            window = overlap_window(schedule[name1],schedule[name2])
            if window is not None:
                pair = (name1,name2)
                conflicts.append((pair,window))
    return conflicts


def main():
    schedule = {
        "standup": (9,10),
        "design review": (9,12),
        "lunch": (12,13),
        "retro": (11,14),
        "one-on-one": (13,14),
    }
    for name in sorted(schedule):
        print(f"{name:<14} {format_interval(schedule[name])}")
    print()
    review = ("design review",schedule["design review"])
    retro = ("retro",schedule["retro"])
    print(describe_pair(review,retro))
    standup = ("standup",schedule["standup"])
    lunch = ("lunch",schedule["lunch"])
    print(describe_pair(standup,lunch))
    print()
    for pair,window in find_conflicts(schedule):
        name1,name2 = pair
        print(f"CONFLICT: {name1} vs {name2} at {format_interval(window)}")


if __name__ == "__main__":
    main()

