def parse_csv_line(csv_line):
    """Split one line of unquoted CSV data into a list of field strings."""
    if not isinstance(csv_line, str):
        raise TypeError("csv_line must be a str")
    return csv_line.rstrip("\r\n").split(",")

def clean_fields(fields):
    """Return each field without its surrounding blanks."""
    return [field.strip() for field in fields]

def classify_field(field):
    """Return a short type name for a raw CSV field."""
    if field == "":
        return "empty"
    if field.lstrip("+-").isdigit():
        return "int"
    try:
        float(field)
    except ValueError:
        return "text"
    return "float"

def describe_row(fields):
    """Summarise a row as 'value(type)' entries."""
    parts = ["%s(%s)" % (field, classify_field(field)) for field in fields]
    return " ".join(parts)

def parse_table(lines):
    """Parse many CSV lines, returning cleaned rows of equal length."""
    rows = [clean_fields(parse_csv_line(line)) for line in lines]
    widths = {len(row) for row in rows}
    if len(widths) > 1:
        raise ValueError("inconsistent column counts: %s" % sorted(widths))
    return rows

def column_widths(rows):
    """Compute the display width needed for each column."""
    if not rows:
        return []
    return [max(len(row[i]) for row in rows) for i in range(len(rows[0]))]

def format_row(fields, widths):
    """Render one row as a padded line of pipe-delimited cells."""
    cells = [fields[i].ljust(widths[i]) for i in range(len(fields))]
    return " | ".join(cells)

def format_table(rows):
    """Render all rows as aligned text lines."""
    widths = column_widths(rows)
    return [format_row(row, widths) for row in rows]

def sum_ints(rows, index):
    """Add up one column, reading each cell as an integer."""
    return sum(int(row[index]) for row in rows)

def sum_floats(rows, index):
    """Add up one column, reading each cell as a float."""
    return sum(float(row[index]) for row in rows)

def main():
    inventory = [
        "name,count,price",
        "nails,500,0.02",
        "hammer,12,9.99",
        "saw,3,24.50",
    ]
    rows = parse_table(inventory)
    for text in format_table(rows):
        print(text)

    header = rows[0]
    data = rows[1:]
    print(", ".join(header))
    for row in data:
        print(describe_row(row))

    units = sum_ints(data, 1)
    price_total = sum_floats(data, 2)
    print("rows=%d" % len(data))
    print("units=%d" % units)
    print("price_total=%.2f" % price_total)

if __name__ == "__main__":
    main()

