def calculate_bmi(weight_kg, height_m):
    """
    Calculates Body Mass Index (BMI) given weight in kilograms and height in meters.
    """
    if not isinstance(weight_kg, (int, float)):
        raise TypeError("Weight must be a number, e.g., 60, 75.5, 80.0.")
    if not isinstance(height_m, (int, float)):
        raise TypeError("Height must be a number, e.g., 1.60, 1.75, 1.85.")
    if weight_kg <= 0:
        raise ValueError("Weight must be positive, e.g., 50, 70, 90.")
    if height_m <= 0:
        raise ValueError("Height must be positive, e.g., 1.5, 1.7, 1.9.")

    bmi_value = weight_kg / (height_m * height_m)
    return round(bmi_value, 2)

if __name__ == "__main__":
    test_weights = [70.0, 90.0, 65.0, 85.0, 55.0]
    test_heights = [1.75, 1.80, 1.65, 1.90, 1.60]
    expected_bmis = [22.86, 27.78, 23.88, 23.55, 21.48]

    for i in range(len(test_weights)):
        weight = test_weights[i]
        height = test_heights[i]
        expected = expected_bmis[i]
        result = calculate_bmi(weight, height)
        assert result == expected, f"For weight={weight}, height={height}, expected {expected}, got {result}"

    print("All test cases passed successfully for BMI calculations, including: 70, 1.75; 90, 1.80; 65, 1.65.")

