def proper_divisors(number):
    """Return the sorted proper divisors of a positive integer."""
    if type(number) is not int:
        raise TypeError("number must be an int")
    if number < 1:
        raise ValueError("number must be positive")
    divisors = set()
    if number > 1:
        divisors.add(1)
    candidate = 2
    while candidate * candidate <= number:
        if number % candidate == 0:
            divisors.update([candidate, number // candidate])
        candidate += 1
    divisors.discard(number)
    return sorted(divisors)


def is_perfect_number(number):
    """Return True when number equals the sum of its proper divisors."""
    return sum(proper_divisors(number)) == number


def classify(number):
    """Label a number as 'perfect', 'abundant' or 'deficient'."""
    total = sum(proper_divisors(number))
    if total == number:
        return "perfect"
    if total > number:
        return "abundant"
    return "deficient"


def format_sum(number):
    """Render the divisor sum of number as a readable equation."""
    divisors = proper_divisors(number)
    if not divisors:
        return "{} has no proper divisors".format(number)
    pieces = " + ".join(str(divisor) for divisor in divisors)
    equation = "{} = {}".format(pieces, sum(divisors))
    return "{} -> {}".format(equation, number)


def perfect_numbers_up_to(limit):
    """Collect every perfect number in the range 1..limit."""
    return [value for value in range(2, limit + 1) if is_perfect_number(value)]


def report_line(number):
    """Describe one number: its label and its divisor sum."""
    header = "{:>6}  {:<10}".format(number, classify(number))
    return "{} {}".format(header, format_sum(number))


def main():
    samples = [
        1,
        6,
        12,
        28,
        100,
        496,
    ]
    for number in samples:
        print(report_line(number))
    limit = 10000
    found = perfect_numbers_up_to(limit)
    joined = ", ".join(str(value) for value in found)
    print("perfect numbers up to {}: {}".format(limit, joined))


if __name__ == "__main__":
    main()

