def is_even(
    number,
    *,
    check_type=True,
    allow_float=False,
    verbose=False
):
    if check_type:
        type_checks = (
            int,
            bool,
            float
        )
        if not isinstance(number, type_checks):
            raise TypeError(
                "Input must be an integer,",
                " or optionally a float.",
                " Received:", type(number)
            )

        if not isinstance(number, int) and not allow_float:
            raise TypeError(
                "Input must be an integer,",
                " float not allowed.",
                " Received:", type(number)
            )

    if allow_float and isinstance(number, float):
        if number != int(number):
            if verbose:
                print(
                    "Warning: Non-integer float provided,",
                    " treating as odd.",
                    f"Number: {number}"
                )
            return False
        number = int(number)

    result = number % 2 == 0

    if verbose:
        print(
            f"Checking if {number} is even.",
            f"Result: {result}",
            "This was a verbose check."
        )

    return result

