def validate_event(event):
    if not isinstance(event, tuple):
        raise TypeError("an event must be a tuple")
    if len(event) != 2:
        raise TypeError("an event needs a start time and an end time")
    for value in event:
        if isinstance(value, bool):
            raise TypeError("event times must not be booleans")
        if not isinstance(value, int):
            raise TypeError("event times must be integers")
    start, end = event
    if start > end:
        raise ValueError("start time must not exceed end time")
    return start, end


def check_event_overlap(event1, event2):
    start1, end1 = validate_event(event1)
    start2, end2 = validate_event(event2)
    return start1 < end2 and start2 < end1


def find_conflicts(events):
    ordered = sorted(validate_event(event) for event in events)
    conflicts = []
    for index, current in enumerate(ordered):
        for other in ordered[index + 1:]:
            if check_event_overlap(current, other):
                conflicts.append((current, other))
    return conflicts


def merge_events(events):
    merged = []
    for start, end in sorted(validate_event(event) for event in events):
        if merged and start <= merged[-1][1]:
            previous_start, previous_end = merged[-1]
            latest_end = max(previous_end, end)
            merged[-1] = (previous_start, latest_end)
        else:
            merged.append((start, end))
    return merged


def format_time(minutes):
    return "{:02d}:{:02d}".format(minutes % 1440 // 60, minutes % 60)


def format_event(event):
    start, end = validate_event(event)
    return "{}-{}".format(format_time(start), format_time(end))


def build_report(events):
    lines = ["Schedule: " + ", ".join(format_event(event) for event in events)]
    for first, second in find_conflicts(events):
        lines.append("Conflict: {} vs {}".format(format_event(first), format_event(second)))
    blocks = merge_events(events)
    lines.append("Busy blocks: " + ", ".join(format_event(block) for block in blocks))
    return "\n".join(lines)


def main():
    schedule = [
        (540, 600),
        (585, 630),
        (700, 760),
        (755, 800),
    ]
    first = schedule[0]
    second = schedule[1]
    overlap = check_event_overlap(first, second)
    label = "{} & {}".format(format_event(first), format_event(second))
    print("{} -> {}".format(label, overlap))
    print(build_report(schedule))


if __name__ == "__main__":
    main()

