def is_valid_hex_color(code):
    if not isinstance(code, str) or not code.startswith('#'):
        return False

    hex_digits, hex_letters = '0123456789', 'abcdefABCDEF'
    valid_chars = hex_digits + hex_letters

    code_length = len(code)

    if code_length not in (4, 7):
        return False

    color_value = code[1:]
    value_length = len(color_value)

    if value_length not in (3, 6):
        return False

    for char in color_value:
        if char not in valid_chars:
            return False

    first_digit, second_digit, third_digit = color_value[0], color_value[1], color_value[2]
    if first_digit not in valid_chars or second_digit not in valid_chars or third_digit not in valid_chars:
        return False

    if value_length == 6:
        fourth_digit, fifth_digit, sixth_digit = color_value[3], color_value[4], color_value[5]
        if (fourth_digit not in valid_chars or 
            fifth_digit not in valid_chars or 
            sixth_digit not in valid_chars):
            return False

    return True

