def build_failure_table(pattern):
    table = [0] * len(pattern)
    length = 0
    for index in range(1, len(pattern)):
        while length > 0 and pattern[index] != pattern[length]:
            length = table[length - 1]
        if pattern[index] == pattern[length]:
            length += 1
        table[index] = length
    return table


def validate_inputs(text, pattern):
    pairs = [
        ('text', text),
        ('pattern', pattern),
    ]
    for name, value in pairs:
        if not isinstance(value, str):
            raise TypeError('%s must be a string, got %s' % (name, type(value).__name__))


def find_all_occurrences(text, pattern):
    """Return every starting index where pattern occurs in text (overlaps included)."""
    validate_inputs(text, pattern)
    if not pattern or len(pattern) > len(text):
        return []
    table = build_failure_table(pattern)
    matches = []
    length = 0
    for index, char in enumerate(text):
        while length > 0 and char != pattern[length]:
            length = table[length - 1]
        if char == pattern[length]:
            length += 1
        if length == len(pattern):
            matches.append(index - length + 1)
            length = table[length - 1]
    return matches


def highlight(text, pattern):
    """Wrap each non-overlapping occurrence of pattern with square brackets."""
    indices = find_all_occurrences(text, pattern)
    pieces = []
    cursor = 0
    for start in indices:
        if start < cursor:
            continue
        pieces.append(text[cursor:start])
        pieces.append('[' + pattern + ']')
        cursor = start + len(pattern)
    pieces.append(text[cursor:])
    return ''.join(pieces)


def describe(text, pattern):
    indices = find_all_occurrences(text, pattern)
    fields = ['hits=%d' % len(indices)]
    fields.append('at=%s' % indices)
    fields.append('marked=%s' % highlight(text, pattern))
    return ' | '.join(fields)


def main():
    samples = [
        ('ababab', 'aba'),
        ('hello world', 'o'),
        ('mississippi', 'issi'),
    ]
    for text, pattern in samples:
        report = describe(text, pattern)
        print('%-12s %s' % (text, report))


if __name__ == '__main__':
    main()

