SEQUENCE_TYPES = (list, tuple)


def validate_pairs(key_value_list):
    """Check that the input is a list of [key, value] pairs and report problems."""
    if not isinstance(key_value_list, SEQUENCE_TYPES):
        raise TypeError("expected a list of [key, value] pairs")
    problems = []
    for index, pair in enumerate(key_value_list):
        if not isinstance(pair, SEQUENCE_TYPES):
            problems.append((index, "not a sequence"))
        elif len(pair) != 2:
            problems.append((index, "length %d, expected 2" % len(pair)))
        else:
            try:
                hash(pair[0])
            except TypeError:
                problems.append((index, "unhashable key"))
    return problems


def list_to_dict(key_value_list):
    """Convert [[key, value], ...] into a dict, last value winning on duplicates."""
    problems = validate_pairs(key_value_list)
    if problems:
        index, reason = problems[0]
        raise ValueError("bad pair at position %d: %s" % (index, reason))
    result = {}
    for key, value in key_value_list:
        result[key] = value
    return result


def duplicate_keys(key_value_list):
    """Return the keys that appear more than once, in order of first appearance."""
    counts = {}
    order = []
    for key, _value in key_value_list:
        if key not in counts:
            order.append(key)
        counts[key] = counts.get(key, 0) + 1
    return [key for key in order if counts[key] > 1]


def format_report(key_value_list):
    """Build a short human readable summary of a conversion."""
    mapping = list_to_dict(key_value_list)
    repeated = duplicate_keys(key_value_list)
    lines = ["pairs: %d" % len(key_value_list)]
    lines.append("keys: %d" % len(mapping))
    for key in sorted(mapping, key=repr):
        lines.append("  %r -> %r" % (key, mapping[key]))
    if repeated:
        lines.append("overwritten: %s" % ", ".join(repr(k) for k in repeated))
    return "\n".join(lines)


def main():
    samples = [
        [
            ['a', 1],
            ['b', 2],
        ],
        [
            ['x', 10],
            ['y', 20],
            ['x', 30],
        ],
        [
            ('mode', 'fast'),
            ('retries', 3),
            ('mode', 'safe'),
            ('timeout', 1.5),
        ],
        [],
    ]
    for sample in samples:
        print(format_report(sample))
        print('-' * 24)
    broken = [
        ['ok', 1],
        ['incomplete'],
    ]
    try:
        list_to_dict(broken)
    except ValueError as error:
        print("rejected: %s" % error)


if __name__ == '__main__':
    main()

