import re

SEPARATOR_CHARS = ('-', ' ')
PATTERNS = (r'\d{10}', r'\d{3}[- ]\d{3}[- ]\d{4}')
BLOCK_SIZES = (
    3,
    3,
    4,
)
FIELD_LABELS = (
    'area',
    'exchange',
    'line',
)
_COMPILED = tuple(re.compile(pattern) for pattern in PATTERNS)


def is_valid_us_phone_number(value):
    """Return True when value is 10 digits, optionally split by hyphens or spaces."""
    if not isinstance(value, str):
        return False
    candidate = value.strip()
    for pattern in _COMPILED:
        if pattern.fullmatch(candidate):
            return True
    return False


def digits_only(value):
    """Extract the digit characters of value, dropping hyphens and spaces."""
    return "".join(ch for ch in value if ch.isdigit())


def split_parts(value):
    """Split the digits of value into area, exchange and line blocks."""
    digits = digits_only(value)
    parts = []
    start = 0
    for size in BLOCK_SIZES:
        parts.append(digits[start:start + size])
        start += size
    return parts


def format_phone_number(value):
    """Render a valid number in the canonical '(123) 456-7890' style."""
    if not is_valid_us_phone_number(value):
        raise ValueError("cannot format invalid number: {!r}".format(value))
    return "({}) {}-{}".format(*split_parts(value))


def describe_parts(value):
    """Label each block of a valid number."""
    parts = split_parts(value)
    labelled = []
    for index, label in enumerate(FIELD_LABELS):
        labelled.append("{} {}".format(label, parts[index]))
    return ", ".join(labelled)


def rejection_reason(value):
    """Explain why value failed validation."""
    if not isinstance(value, str):
        return "not a string"
    candidate = value.strip()
    allowed = set("0123456789") | set(SEPARATOR_CHARS)
    stray = sorted(set(candidate) - allowed)
    if stray:
        return "illegal characters: {}".format(", ".join(repr(c) for c in stray))
    count = len(digits_only(candidate))
    if count != 10:
        return "expected 10 digits, found {}".format(count)
    return "separators are misplaced"


def describe(value):
    """Build a one-line verdict for value."""
    if is_valid_us_phone_number(value):
        canonical = format_phone_number(value)
        verdict = "VALID   {} -> {}".format(describe_parts(value), canonical)
    else:
        verdict = "INVALID {}".format(rejection_reason(value))
    return "{!r:20} {}".format(value, verdict)


def build_report(numbers):
    header = ["US phone number validation report", "-" * 34]
    return header + [describe(number) for number in numbers]


def main():
    samples = [
        '123-456-7890',
        '123 456 7890',
        '1234567890',
        '(123) 456-7890',
        '123-45-67890',
        '123.456.7890',
        '123-456-789',
        55512345678,
    ]
    print("\n".join(build_report(samples)))
    accepted = [number for number in samples if is_valid_us_phone_number(number)]
    print("\n{} of {} samples accepted".format(len(accepted), len(samples)))


if __name__ == '__main__':
    main()

