from urllib.parse import quote, unquote_plus

MISSING = '<missing>'


def split_url(url):
    """Return the address part of a URL and its raw query string."""
    address = url.partition('#')[0]
    parts = address.partition('?')
    return parts[0], parts[2]


def parse_url_params(url):
    """Parse the query parameters of a URL into a dictionary."""
    if not isinstance(url, str):
        raise TypeError('parse_url_params() expects a string URL')
    query = split_url(url)[1]
    params = {}
    for pair in query.split('&'):
        if not pair:
            continue
        piece = pair.partition('=')
        key = unquote_plus(piece[0])
        if not key:
            continue
        params[key] = unquote_plus(piece[2])
    return params


def build_query(params):
    """Rebuild a query string from a parameter dictionary."""
    pieces = []
    for key in sorted(params, key=str.lower):
        encoded_key = quote(key, safe='')
        encoded_value = quote(params[key], safe='')
        pieces.append('{}={}'.format(encoded_key, encoded_value))
    return '&'.join(pieces)


def describe_params(params):
    """Return the number of parameters and a readable list of their names."""
    names = ', '.join(sorted(params, key=str.lower))
    return len(params), names


def pick(params, wanted):
    """Select a subset of parameters, substituting a marker when absent."""
    return {name: params.get(name, MISSING) for name in wanted}


def format_report(url, wanted):
    """Produce a multi-line report about the query parameters of one URL."""
    base, query = split_url(url)
    params = parse_url_params(url)
    count, names = describe_params(params)
    lines = ['address: {}'.format(base)]
    lines.append('raw query: {!r}'.format(query))
    lines.append('found {} parameter(s): {}'.format(count, names or '-'))
    selected = pick(params, wanted)
    for key, value in selected.items():
        lines.append('  {} = {}'.format(key, value))
    lines.append('canonical: {}'.format(build_query(params) or '-'))
    return '\n'.join(lines)


def main():
    urls = [
        'http://example.com?name=Alice&age=30',
        'http://example.com/path',
        'https://search.example.org/find?q=hello+world&page=2#results',
        'http://example.net?flag=&name=Bob%20Smith',
    ]
    wanted = [
        'name',
        'age',
        'q',
    ]
    for url in urls:
        print(format_report(url, wanted))
        print('-' * 40)


if __name__ == '__main__':
    main()

