    return best


def text_statistics(text):
    """Bundle the interesting counts of a text into a dictionary."""
    lines = split_lines(text)
    return dict(
        total=count_lines_in_text(text),
        non_empty=count_non_empty_lines(text),
        words=sum(len(line.split()) for line in lines),
        characters=len(text),
        longest=longest_line(text),
    )


def format_report(label,stats):
    """Render one statistics dictionary as a single readable line."""
    fields = [
        "lines={total}".format(**stats),
        "non-empty={non_empty}".format(**stats),
        "words={words}".format(**stats),
        "chars={characters}".format(**stats),
    ]
    return "{0:<12} {1}".format(label + ":",", ".join(fields))


def main():
    samples = [
        ("three","Line 1\nLine 2\nLine 3"),
        ("single","Single line text."),
        ("empty",""),
        ("trailing","alpha\nbeta\n"),
        ("blanks","first\n\n\nlast line here\n"),
    ]
    grand_total = 0
    for label,text in samples:
        stats = text_statistics(text)
        grand_total += stats["total"]
        print(format_report(label,stats))
        if stats["longest"]:
            print("             longest: {0!r}".format(stats["longest"]))
    print("grand total of lines: {0}".format(grand_total))


if __name__ == "__main__":
    main()
